import java.util.*;
import java.util.concurrent.*;

public class OrderBatchFetcher {
    private final ExecutorService ioExecutor = Executors.newVirtualThreadPerTaskExecutor();
    private final Semaphore dbConcurrencyLimit = new Semaphore(32);

    public List<Order> fetchOrders(List<String> orderIds) {
        List<CompletableFuture<Order>> futures = orderIds.stream()
            .map(id -> CompletableFuture.supplyAsync(() -> fetchWithLimit(id), ioExecutor)
                                        .orTimeout(2, TimeUnit.SECONDS))
            .toList();
        return futures.stream().map(CompletableFuture::join).toList();
    }

    private Order fetchWithLimit(String id) {
        try {
            if (!dbConcurrencyLimit.tryAcquire(2, TimeUnit.SECONDS)) {
                throw new CompletionException(new TimeoutException("DB semaphore busy"));
            }
            try {
                return queryOrderDb(id); // uses socket timeout = 2s
            } finally {
                dbConcurrencyLimit.release();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new CompletionException(e);
        }
    }
}

